import sys
import math

MOD = 998244353
MAX = int(4e5) + 10
factorials = [1] * MAX
invFactorials = [1] * MAX

def initialize():
    for i in range(1, MAX):
        factorials[i] = (factorials[i - 1] * i) % MOD
        invFactorials[i] = (invFactorials[i - 1] * modInverse(i, MOD)) % MOD

def nCr(n, r):
    return (factorials[n] * invFactorials[r] % MOD) * invFactorials[n - r] % MOD

def binPow(base, exp):
    result = 1
    b = base % MOD
    e = exp
    while e > 0:
        if e & 1:
            result = (result * b) % MOD
        b = (b * b) % MOD
        e >>= 1
    return result

def extendedEuclidean(a, b):
    if a == 0:
        return (b, 0, 1)
    gcd, x1, y1 = extendedEuclidean(b % a, a)
    x = y1 - (b // a) * x1
    y = x1
    return (gcd, x, y)

def modInverse(a, m):
    gcd, x, _ = extendedEuclidean(a, m)
    if gcd != 1:
        return -1
    return (x % m + m) % m

def execute():
    initialize()
    input_data = sys.stdin.read().strip().split()
    n = int(input_data[0])
    k = int(input_data[1])
    if k == 0:
        print(factorials[n])
        return
    if n <= k:
        print(0)
        return
    answer = nCr(n, k)
    remainingCols = n - k
    total = 0
    for i in range(remainingCols + 1):
        tempVal = nCr(remainingCols, i)
        tempVal = (tempVal * binPow(remainingCols - i, n)) % MOD
        if i & 1:
            total -= tempVal
            if total < 0:
                total += MOD
        else:
            total += tempVal
            if total >= MOD:
                total -= MOD
    print((2 * ((answer * total) % MOD)) % MOD)

if __name__ == "__main__":
    execute()

